cat >> tests/test_validation.py <<'EOF'


@pytest.mark.parametrize("filename", ["a.pdf", "a.PDF", "a.Png", "a.csv", "a.CsV"])
def test_allowed_extensions_are_accepted_in_any_case(filename):
    """The extension check ignores case."""
    assert validate_upload(filename, 1) == filename.lower()


@pytest.mark.parametrize("filename", ["a.exe", "a.pdf.exe", "a", "pdf", "a.", "a.jpeg"])
def test_other_extensions_are_rejected(filename):
    """Anything outside pdf, png and csv is refused."""
    with pytest.raises(UploadRejected, match="extension"):
        validate_upload(filename, 1)


@pytest.mark.parametrize("filename", ["dir/a.pdf", "dir\\a.pdf", "../a.pdf", "..\\a.pdf", "/a.pdf"])
def test_path_separators_are_rejected_not_repaired(filename):
    """A forward or back slash anywhere in the name is refused."""
    with pytest.raises(UploadRejected, match="path separator"):
        validate_upload(filename, 1)


@pytest.mark.parametrize("filename", [".hidden.pdf", ".pdf", "..a.pdf"])
def test_leading_dot_is_rejected(filename):
    """A name starting with a dot is refused."""
    with pytest.raises(UploadRejected, match="start with a dot"):
        validate_upload(filename, 1)


def test_stored_name_is_lowercased():
    """The returned name is the filename in lowercase."""
    assert validate_upload("Report Q1.PDF", 1) == "report q1.pdf"
